corrected_code:
from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework.exceptions import PermissionDenied
from rest_framework import status
from django.http import FileResponse, Http404
from .models import BackgroundExportJob

class DownloadAuditExportCSVView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, export_job_id: str):
        try:
            job = BackgroundExportJob.objects.get(id=export_job_id)
        except BackgroundExportJob.DoesNotExist:
            raise Http404("Export job not found")

        # Verify that the export job was initiated by the caller or belongs to their organization
        if job.organization != request.user.organization and not request.user.is_staff:
            raise PermissionDenied("You do not have permission to download this export file")

        if not job.csv_file:
            return Response({'error': 'Export job is still processing'}, status=status.HTTP_202_ACCEPTED)

        return FileResponse(job.csv_file.open('rb'), as_attachment=True, filename=job.filename)
